INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('quiwan-li', 'Quiwan Li', NULL, 'High Lord Necromancer (self-assigned; also known as Master Li)', 'rifts', 'Human, Chinese', '13th level Russian/Chinese Necromancer', 13, 'Aberrant evil, but seems sincere about destroying Xiticix and demons', 'Looks late forties or early fifties; claims to be 226 years old', '5 feet 8 inches (1.73 m)', '140 lbs (63 kg)', '{"IQ":14,"ME":15,"MA":22,"PS":20,"PP":19,"PE":21,"PB":10,"Spd":12}', 169, 240, NULL, 198, NULL, NULL, NULL, '{"attacks":6,"initiative":2,"strike":4,"parry":7,"dodge":7,"roll":4,"pull":3,"damage":9}', 'S.D.C. 240 is printed as the equivalent of 4 M.D.C. (the book says not to ask how). Damage +9 is S.D.C. damage from P.S. bonus. Critical strike on natural 18-20, judo body throw, all kick attacks, Karate-style kick 2D4, paired weapons. +4 to save vs poison and magic, +5 vs Necromancy magic, +6 vs Horror Factor. 70% likelihood of evoking trust or intimidation. Combat skill: Martial Arts at 13th level proficiency.', '[{"name":"Basic Math","pct":98},{"name":"Lore: Monsters & Demons","pct":98},{"name":"Lore: Russian & Chinese Demons & Monsters","pct":98},{"name":"Art","pct":98},{"name":"Calligraphy","pct":98},{"name":"Writing","pct":98},{"name":"Literate in Chinese","pct":98},{"name":"Literate in Euro","pct":98},{"name":"Speaks Chinese","pct":98},{"name":"Speaks Euro","pct":98},{"name":"Speaks English","pct":98},{"name":"Skin & Prepare Animal Hides & Bones","pct":95},{"name":"Wilderness Survival","pct":95}]', 'Printed as Skills of Note: the 98% group covers literacy in Chinese and Euro, speech in Chinese, Euro and English, Basic Math, the two Lore skills, Art, Calligraphy and Writing; Skin & Prepare Animal Hides & Bones and Wilderness Survival are 95%. W.P. Automatic Pistol, W.P. Revolver, W.P. Knife and W.P. Blunt, all at 13th level proficiency. Martial Arts at 13th level proficiency.', 'Claims to be centuries old and has a body far sturdier than a normal human body, with S.D.C. rated at the equivalent of a few M.D.C.; he will not explain it. His Necromancer powers let him join with the dead, graft extra limbs on himself and raise and command corpses.', 'Necromancer (Russian/Chinese): Bone Magic levels 1-5, plus Wear the Face of Another, Poison Touch, Mock Funeral, Funeral Pyre, Fragile Bone to M.D.C. Bone, Greater Animated Dead, Bone Staff and Transfer Life Force. Conventional spells: Death Trance, Fear, Aura of Death, Aura of Doom, Globe of Daylight, Lantern Light, Concealment, Fire Ball, Cloak of Darkness, Shadow Meld, Breathe Without Air, Life Source, Ley Line Transmission, Commune with Spirits, Repel Animals, Turn Dead, Constrain Being, Exorcism, Sickness, Spoil, Armorbane, Restore Limb and Tongues. P.P.E.: 198. Special Necromancer Powers (see Rifts Mystic Russia pp.83-107; Rifts Africa is similar but has no Bone Magic): 1. Union with the Dead. 2. Augmentation with Additional Appendages. 3. Animate and Control Dead. Per the general notes on the Deathbringer Necromancers (printed 105), in combat they attach 2-6 Xiticix arms to themselves and animate a legion of dead Xiticix Warriors.', 'None, although he claims to be visited by visions and insight.', NULL, 'None and will avoid them like the plague.', 'Tends to rely on cunning, magic knowledge, Necro-powers and animated dead. Body Armor: creates a suit of Necro-Armor from a dead Xiticix or any corpse as needed, 169 M.D.C. and Horror Factor 13. Necromancers wear a headdress made from the skulls of slain Xiticix Hunters or Super-Warriors and a cape made from their wings (general Deathbringer note, printed 105).', NULL, 'Calm, soft-spoken and confident; he projects wisdom and sincerity and never raises his voice, so his followers trust and obey him without question. Insane in two ways: obsessed with wiping out demons and demonic monsters, and fond of surrounding himself with skeletons, zombies and bones. Phobia of the gods of light, especially Anubis.', 'Deathbringer Necromancer disciples and Deathbringer Psi-Stalkers; cooperating with the Kingdom of Lazlo against the Xiticix', 'Xiticix; demons and demonic monsters; the gods of light (phobia)', 'Quiwan Li is the mysterious founder and leader of the Deathbringer cult of Necromancers living among a small Psi-Stalker tribe near Thunder Bay. He says he escaped enslavement by demons in China and offers his warriors to the Lazlo war effort, though the Lazlo heroes suspect a hidden agenda. He and four trusted high-level disciples plus two dozen Psi-Stalkers plan to sit out the fighting to prepare for a later war against demonkind.', 'Rifts World Book 23: Xiticix Invasion p.105-107'),
('brok-magnil', 'Brok Magnil', 'Brok Magnil (likes to call himself Deathstrike)', 'Evil Necromancer', 'rifts', 'Human; born in Manitoba', '7th level Russian/Chinese Necromancer', 7, 'Diabolic evil', '32', '6 feet (1.8 m)', '160 lbs', '{"IQ":12,"ME":14,"MA":12,"PS":23,"PP":20,"PE":21,"PB":10,"Spd":12}', 69, 40, NULL, 131, NULL, NULL, NULL, '{"attacks":5,"initiative":1,"strike":4,"parry":5,"dodge":5,"roll":3,"pull":3,"damage":7}', 'Damage +7 is S.D.C. damage. Critical strike on natural 18-20, judo body throw, all kick attacks, Karate-style kick 2D4, paired weapons. +3 to save vs poison and magic, +5 vs Necromancy magic, +6 vs Horror Factor. Combat skill: Martial Arts at 7th level proficiency. The general Deathbringer notes (printed 107) say Necromancers of 5th level or higher usually create Necro-Armor with 65 M.D.C. at 5th level (+13 per level of experience) and Horror Factor 13; his own block prints no Necro-Armor M.D.C. figure, only that he knows the spell.', '[{"name":"Basic Math","pct":98},{"name":"Lore: Monsters & Demons","pct":98},{"name":"Swim","pct":98},{"name":"Literate in Euro","pct":98},{"name":"Speaks Euro","pct":98},{"name":"Speaks English","pct":98},{"name":"Skin & Prepare Animal Hides & Bones","pct":75},{"name":"Wilderness Survival","pct":75}]', 'Printed as Skills of Note: literate in Euro, speaks Euro and English, Basic Math, Lore: Monsters & Demons and swim, all 98%; Skin & Prepare Animal Hides & Bones and Wilderness Survival 75%. W.P. Energy Rifle, W.P. Knife and W.P. Blunt at 7th level proficiency. Martial Arts at 7th level proficiency.', 'No unusual physical traits. His Necromancer powers let him join with the dead, add extra appendages to himself and animate and command corpses.', 'Necromancer (Russian/Chinese): Bone Magic levels 1-3, plus Command Ghouls, Necro-Armor, Wear the Face of Another, Poison Touch, Mock Funeral, Funeral Pyre, Fragile Bone to M.D.C. Bone, Greater Animated Dead, Bone Staff and Transfer Life Force. Conventional spells: Death Trance, Fear, Aura of Death, Aura of Doom, Globe of Daylight, Lantern Light, Concealment, Fire Ball, Cloak of Darkness, Shadow Meld, Breathe Without Air, Life Source, Ley Line Transmission, Commune with Spirits, Repel Animals, Turn Dead, Constrain Being, Exorcism, Sickness, Spoil, Armorbane, Restore Limb and Tongues. P.P.E.: 131. Special Necromancer Powers (see Rifts Mystic Russia pp.83-107; Rifts Africa is similar but has no Bone Magic): 1. Union with the Dead. 2. Augmentation with Additional Appendages. 3. Animate and Control Dead.', 'None.', NULL, 'None and will avoid them like the plague.', 'Relies on cunning, treachery, magic knowledge, Necro-powers and animated dead, but will do anything to get his way. Carries a concealed ion pistol and a Wilk Laser Wand (printed with a possessive; no damage, range or payload printed). Knows the Necro-Armor spell (see bonuses_note for the general armor figures).', NULL, 'Arrogant, cocky, hedonistic and cruel. He craves the power and glory of a king right now and bristles when told what to do or when his suggestions are ignored. He holds grudges against heroes who oppose or embarrass him. Insane: obsessed with gaining power, with sadistic tendencies.', NULL, 'Heroes who oppose him, make him look bad or get in his way; fears Master Li would oppose his plans', 'Brok Magnil is a 7th level Deathbringer Necromancer among the disciples of Master Li, who has no interest in the demon-slaying cause or the Xiticix war. He plans to desert the cult during the war, possibly faking his death, and head for the Magic Zone or east to carve out his own kingdom by intimidation. The book suggests developing him as a recurring villain.', 'Rifts World Book 23: Xiticix Invasion p.107-108'),
('raskin-free-thinker', 'Raskin', NULL, 'Free Thinker', 'rifts', 'Human', '12th level Rogue Scientist', 12, 'Scrupulous good.', '41', '6 feet, 2 inches (1.88 m)', '180 lbs (81.7 kg)', '{"IQ":24,"ME":19,"MA":17,"PS":11,"PP":12,"PE":11,"PB":12,"Spd":11}', 59, 30, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"strike":2,"parry":3,"dodge":3,"roll":4,"pull":4,"damage":2}', 'Kick 1D6. Critical Strike on a natural 19-20. Body Throw/Flip 1D6 plus victim loses one attack and initiative.', '[]', 'No absolute percentages printed; bonuses only: Computer Operation (+30%), Land Navigation (+14%), Literacy (+10%), Advanced Mathematics (+30%), Radio: Basic (+20%), Read Sensory Equipment (+20%), Basic Electronics (+20%), Pilot Automobile (+10%), Wilderness Survival (+15%), Criminal Science & Forensics (+15%), First Aid (+15%), Paramedic (+15%), Medical Doctor (+15%), M.D. in Cybernetics (+15%), Pathology (+15%), Pilot Airplane (+20%), Pilot Helicopter (+20%), Pilot Motorcycle (+20%), Pilot Truck (+20%), Navigation (+20%), Computer Hacking (+10%), Anthropology (+30%), Archaeology (+30%), Astronomy (+30%), Biology (+30%), Botany (+30%), Chemistry (+30%), Chemistry: Analytical (+30%), Computer Programming (+10%), Writing (+10%). Without a figure: W.P. Energy Pistol, W.P. Energy Rifle. Hand to Hand: Basic. Printed under Skills of Note.', NULL, 'None.', 'None.', NULL, 'None.', 'C-20 Laser Pistol: Mega-Damage 2D6, rate of fire equal to hand to hand attacks per melee, range 800 feet (244 m), payload 30 shots per long E-Clip. Extra ammo: 6 long E-clips, 3 standard E-clips. Body armor: battered Urban Warrior armor with only 39 M.D.C. left. Other: standard starting equipment plus an NGS2 Basic Survival Pack.', 'Millions stashed away to fund his scientific research, much of it stolen from the Coalition.', 'A dreamy big-picture thinker who lives in abstract science; he relies on his practical wife Illyana to keep him on task.', 'Illyana (wife), Free Thinkers', 'Coalition States, Xiticix', 'Raskin is a veteran Free Thinker and Rogue Scientist, one of the founding figures of the group behind the Xiticix virus scheme. He is the first of the Dramatis Personae for the Hivelands adventure, a human scientist funding research with stolen Coalition money.', 'Rifts World Book 23: Xiticix Invasion p.133-134'),
('illyana-free-thinker', 'Illyana', NULL, NULL, 'rifts', 'Human', '12th level Rogue Scientist', 12, 'Principled good.', '40', '5 feet, 8 inches (1.73 m)', '150 lbs (68.1 kg)', '{"IQ":24,"ME":20,"MA":10,"PS":10,"PP":10,"PE":10,"PB":15,"Spd":16}', 57, 20, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"strike":2,"parry":3,"dodge":3,"roll":4,"pull":4,"damage":2}', 'Kick 1D6. Critical Strike on a natural 19-20. Body Throw/Flip 1D6 plus victim loses one attack and initiative.', '[]', 'No absolute percentages printed; bonuses only: Computer Operation (+30%), Land Navigation (+14%), Literacy (+10%), Advanced Mathematics (+30%), Radio: Basic (+20%), Read Sensory Equipment (+20%), Basic Electronics (+20%), Pilot Automobile (+10%), Wilderness Survival (+15%), Criminal Science & Forensics (+15%), First Aid (+15%), Paramedic (+15%), Medical Doctor (+15%), M.D. in Cybernetics (+15%), Pathology (+15%), Aircraft Mechanics (+20%), Automotive Mechanics (+20%), Locksmith (+20%), Mechanical Engineer (+20%), Robot Mechanics (+20%), Weapons Engineer (+20%), Anthropology (+30%), Archaeology (+30%), Astronomy (+30%), Biology (+30%), Botany (+30%), Chemistry (+30%), Chemistry: Analytical (+30%), Computer Programming (+10%), Writing (+10%). Without a figure: W.P. Energy Pistol, W.P. Energy Rifle. Hand to Hand: Basic. Printed under Skills of Note.', NULL, 'None.', 'None.', NULL, 'None.', 'C-20 Laser Pistol: Mega-Damage 2D6, rate of fire equal to hand to hand attacks per melee, range 800 feet (244 m), payload 30 shots per long E-Clip. Extra ammo: 4 long E-clips, 12 standard E-clips, 3 micro-fusion grenades. Body armor: The Plastic-Man with 31 M.D.C. left. Other: standard starting equipment plus an NGS2 Basic Survival Pack.', 'Same as Raskin (millions); she is the one who keeps the accounts.', 'Level-headed and warm; she lets her husband finish speaking, then smooths over his lapses. Wholly devoted to fighting the Xiticix.', 'Raskin (husband), Free Thinkers', 'Coalition States, Xiticix', 'Illyana is the wife of Raskin and a fellow 12th level Rogue Scientist among the Free Thinkers. She handles the group money and keeps her husband practical, and is an equal partner in the anti-Xiticix crusade.', 'Rifts World Book 23: Xiticix Invasion p.134'),
('cristobal-free-thinker', 'Cristobal', NULL, NULL, 'rifts', 'Human', '10th level Rogue Scholar', 10, 'Principled good.', '37', '5 feet, 9 inches (1.75 m)', '150 lbs (68.1 kg)', '{"IQ":24,"ME":21,"MA":18,"PS":11,"PP":11,"PE":11,"PB":11,"Spd":11}', 59, 20, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"strike":1,"parry":2,"dodge":2,"roll":4,"damage":2}', 'Kick 1D6. Critical Strike on a natural 19-20. Body Throw/Flip 1D6 plus victim loses one attack and initiative.', '[]', 'No absolute percentages printed; bonuses only: Literacy (+60%), Basic Math (+40%), Computer Operations (+30%), Pilot Automobile (+10%), Art (+10%), Computer Programming (+10%), Lore: Demons & Monsters (+10%), Writing (+10%), Photography (+10%), Anthropology (+10%), Archaeology (+10%), Astronomy (+10%), Pilot Airplane (+10%), Streetwise (+10%), Computer Hacking (+10%), Cryptography (+10%), Optic Systems (+10%), Radio: Scramblers (+10%), Radio: Basic (+10%). Without a figure: W.P. Energy Pistol, W.P. Energy Rifle. Hand to Hand: Basic. Printed under Skills of Note.', NULL, 'None.', 'None.', NULL, 'None.', 'NG-57 Northern Gun Heavy-Duty Ion Blaster (2): Mega-Damage 2D4 or 3D6, rate of fire equal to attacks per melee round, range 500 feet (152 m), payload 10 shots per standard E-clip. Extra ammo: 10 standard E-Clips. Fires one blaster dry before switching to the other. Body armor: The Plastic-Man with 35 M.D.C. Other: pre-Rifts solar-powered digital camera (up to 10 hours of footage); a pre-Rifts digital book holding thousands of books, giving +10% to any Technical skill roll (needs a successful Computer Operation roll to use).', 'A few thousand credits; prefers to barter.', 'Gentle bookworm who dislikes violence but fights for his causes: stopping the Xiticix, loosening the Coalition book ban, and recovering pre-Rifts knowledge.', 'Free Thinkers', 'Coalition States, Xiticix', 'Cristobal is a Free Thinker scholar and bibliophile who keeps about 250 pre-Rifts books at the compound. He is a mild, learned member of the group listed in the Hivelands Dramatis Personae.', 'Rifts World Book 23: Xiticix Invasion p.134-135'),
('summers-free-thinker', 'Summers', NULL, NULL, 'rifts', 'Human', '7th level Headhunter', 7, 'Unprincipled good.', '36', '6 feet, 4 inches (1.9 m)', '200 lbs (90.8 kg)', '{"IQ":11,"ME":12,"MA":7,"PS":25,"PP":20,"PE":20,"PB":11,"Spd":32}', 58, 42, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"initiative":2,"pull":3,"roll":5,"parry":8,"dodge":8,"strike":5,"damage":9}', '+3 to save vs poison & magic, +10% to save vs coma/death. Kick 2D4+9, Jump Kick, Entangle, Critical Strike on a natural 18-20, Paired Weapons, Knockout/Stun on a natural 20. S.D.C. note: also see body armor.', '[]', 'No absolute percentages printed; bonuses only: Radio: Basic (+15%), Radio: Scramblers (+10%), Detect Ambush (+10%), Detect Concealment (+15%), Tracking (+10%), Land Navigation (+10%), Weapon Systems (+10%), Read Sensory Equipment (+10%), Pilot Jet Pack (+12%), Pilot Tanks and APCs (+10%), Pilot Motorcycle (+5%), Pilot Hovercraft (+5%), Lore: Demon (+10%). Without a figure: Boxing, Wrestling, Climbing, Swimming, Wilderness Survival, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons, W.P. Heavy, W.P. Sword (+3 to strike and parry). Hand to Hand: Martial Arts.', NULL, 'None.', 'None.', NULL, 'None.', 'C-27 Light Plasma Cannon: 6D6 per blast, rate of fire equal to attacks per melee, range 1,600 feet (printed 488 km), 10 shots per energy canister, +1 to strike. CP-40 Pulse Laser Rifle: 2D6 single or 6D6 triple blast, range 2,000 feet (610 m), 30 shots per long E-Clip. C-20 Laser Pistol: 2D6, range 800 feet (244 m), 30 shots per long E-Clip. Extra ammo: 4 C-27 energy canisters, 8 long E-clips, 4 standard E-clips, 30 micro-fusion grenades in a satchel. Body armor: CA-7 Heavy Dead Boy Armor M.D.C.: Head/Helmet 75, arms 60 each, legs 80 each, main body 100 (a hole in the neck area; otherwise in perfect condition, taken from a Coalition soldier a week ago). Other: camouflage clothing, gas mask & filter, tinted goggles, hatchet, 4 knives (1D6 S.D.C. each), robot medical kit, IRMSS, tent, knapsack, backpack, saddlebags, two canteens, freeze-dried rations for six weeks.', 'None of his own; Raskin supplies him and he scavenges or steals the rest.', 'Gruff, sarcastic and slow to trust, but fiercely loyal once he does. Driven to destroy the Xiticix after they killed his family.', 'Raskin and Illyana, Free Thinkers', 'Xiticix, Coalition States', 'Summers is a hard-bitten Headhunter from the northern badlands and an old friend of Raskin and Illyana, present since the Free Thinkers began. He serves as the group muscle and wears Dead Boy armor taken from a Coalition soldier.', 'Rifts World Book 23: Xiticix Invasion p.135'),
('typical-dead-boy-commando-durango', 'Typical Dead Boy Commando (Strike Force Durango)', NULL, NULL, 'rifts', 'Human', '3rd to 5th level CS Commando', NULL, 'Mostly Anarchist and Unprincipled, but with a strong sense of discipline; always follow their commander orders.', '21-27 (average)', '6 feet (1.83 m) average', '180-200 lbs (81.7 to 90 kg)', '{"IQ":13,"ME":13,"MA":13,"PS":19,"PP":15,"PE":15,"PB":10,"Spd":30}', 45, 45, NULL, NULL, NULL, NULL, NULL, '{"initiative":1,"strike":1,"parry":3,"dodge":3,"roll":5,"pull":3,"damage":3}', 'Attributes in armor: P.S. 27, Spd 44. Attacks per melee: Four or Five (not a single figure). Damage bonus +3, or +15 in armor. +2 to save vs Horror Factor. Body Flip/Throw +1, Body Block/Tackle, Backward Sweep, Disarm, Kick Attack 2D6, Knockout/Stun on natural 20, Pin/Incapacitate 18-20, Crush/Squeeze 1D4+7. HP, S.D.C. and attributes are printed as typical or average figures.', '[]', 'No absolute percentages printed; bonuses only: Math: Basic (+20%), Radio: Basic (+20%), Land Navigation (+10%), Intelligence (+10%), Parachuting (+20%), Pilot: Jet Packs (+10%), Pilot: Robots & Power Armor (+10%), Recognize Weapon Quality (+12%), Wilderness Survival (+15%), Climbing (+10%), Detect Ambush (+10%), Detect Concealment (+10%), Escape Artist (+10%), Tracking (+10%). Without a figure: Radio: Scramblers, Running, Body Building & Weight Lifting, Boxing, Wrestling, Climbing, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons, W.P. Sword (+4 to strike and parry), W.P. Paired Weapons. Hand to Hand: Commando.', NULL, 'None.', 'None.', NULL, 'None.', 'CP-40 Pulse Laser Rifle: 2D6 single or 6D6 triple blast, rate of fire equal to hand to hand attacks, range 2,000 feet (610 m), 30 shots per long E-Clip. C-20 Laser Pistol: 2D6, range 800 feet (244 m), 30 shots per long E-Clip. Vibro-Saber: 2D4 M.D. Extra ammo: 16 long E-Clips. Body armor: CA-6EX Heavy Dead Boy Armor: Head/Helmet 100 M.D.C., arms 100 each, legs 120 each, main body 200; +8 P.S., +14 Spd, +10 ft (3 m) to leaps, reduces fatigue rate by 50%. Other: two flares, two fragmentation grenades, binoculars, robot medical kit, pocket computer, utility belt, air filter & gas mask, walkie-talkie, canteen and food rations.', NULL, 'Disciplined, methodical killers who act fast on orders; precise rather than reckless. The pride of Coalition Special Forces.', 'Coalition States, Strike Force Durango', 'Free Thinkers', 'The rank-and-file Dead Boy commandos of Strike Force Durango, the Coalition team sent after the Free Thinkers and the stolen Lone Star data. Printed as a generic stat block for the unit armored special-forces soldiers.', 'Rifts World Book 23: Xiticix Invasion p.137'),
('typical-cs-elite-rpa-pilot-durango', 'Typical CS Elite RPA Pilot (Strike Force Durango)', NULL, NULL, 'rifts', 'Human', '4th to 6th level Coalition Elite RPA (Robot Power Armor) Pilot', NULL, 'Scrupulous, Unprincipled, or Anarchist, occasionally Aberrant or Miscreant.', '20-25 (average)', '5 feet 10 inches (1.78 m)', '160 lbs (72.6 kg)', '{"IQ":14,"ME":14,"MA":12,"PS":10,"PP":13,"PE":13,"PB":10,"Spd":20}', 40, 50, NULL, NULL, NULL, NULL, NULL, '{"strike":2,"parry":5,"dodge":5,"roll":3}', 'Attacks per melee: Four or five (6 in robot or power armor). Power Armor Combat Bonuses, in addition to the normal ones: +2 attacks per melee, +2 to strike, +2 to parry, +2 to dodge on ground, +5 to dodge while flying (if applicable), +3 to roll with punch/fall/impact, critical strike; punch 1D6 M.D., kick 1D6 M.D., leap kick 2D6 M.D. (counts as two attacks), body flip/throw 1D4 M.D., body block/tackle 1D6 M.D. (counts as two attacks).', '[]', 'No absolute percentages printed; bonuses only: Radio: Basic (+10%), Pilot Automobile (+10%), Pilot Hovercraft (+10%), Pilot Tank & APCs (+15%), Pilot Robots and Power Armor (+10%), Pilot Jet Packs (+10%), Navigation (+10%), Read Sensory Equipment (+15%), Weapon Systems (+15%). Without a figure: Radio: Scramblers, Robot Combat: Elite, Running, Climbing, Body Building & Weight Lifting, Boxing, Wrestling, Wilderness Survival, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons. Hand to Hand: Expert, Power Armor Elite Combat Training.', NULL, 'None.', 'None.', NULL, 'None.', 'CP-40 Pulse Laser Rifle: 2D6 single or 6D6 triple blast, rate of fire equal to hand to hand attacks, range 2,000 feet (610 m), 30 shots per long E-Clip. C-20 Laser Pistol: 2D6, range 800 feet (244 m), 30 shots per long E-Clip. Extra ammo: 16 long E-Clips. Body armor: CA-4 Standard Dead Boy Armor: Head/Helmet 70 M.D.C., arms 60 each, legs 80 each, main body 100; or Power Armor (SAMAS or other; G.M. choice). Other: Power Armor or CS robot vehicle.', NULL, 'Cocky, brash hot-doggers who are nonetheless loyal to the team and follow orders to the letter. Excited by their top-secret experimental assignment.', 'Coalition States, Strike Force Durango', 'Free Thinkers', 'The elite robot and power armor pilots attached to Strike Force Durango, flying retrofitted Coalition machines on a mission against the Free Thinkers. Printed as a generic block, followed by Quick Stats for the unit power armor and robot vehicles.', 'Rifts World Book 23: Xiticix Invasion p.137-138'),
('major-samuel-haim', 'Major Samuel Haim', NULL, 'Intelligence Officer and Base Commander at Fort Barron', 'rifts', 'Human', '9th level Military Specialist (Intelligence), rapidly approaching 10th level', 9, 'Unprincipled', '42', 'Six feet, two inches (1.88 m)', '168 lbs (75.6 kg)', '{"IQ":17,"ME":13,"MA":20,"PS":21,"PP":19,"PE":15,"PB":11,"Spd":14}', 55, 30, NULL, 9, NULL, NULL, NULL, '{"attacks":6,"strike":4,"parry":5,"dodge":5,"roll":2,"pull":2,"damage":6}', 'Damage bonus is S.D.C. damage from P.S. Critical strike on natural 18-20, judo body throw, all kick attacks, paired weapons, 60% likelihood of evoking trust or intimidation. Combat training: CS Officer, Hand to Hand: Expert.', '[{"name":"Climbing","pct":97},{"name":"Swimming","pct":97},{"name":"Demolitions","pct":92},{"name":"Demolitions Disposal","pct":92},{"name":"Pilot Tanks and APCs","pct":86},{"name":"Pilot Hovercraft","pct":98},{"name":"Radio Basic","pct":98},{"name":"Radio Scramblers","pct":98},{"name":"Surveillance Systems","pct":87},{"name":"TV & Video","pct":97},{"name":"Disguise","pct":66},{"name":"Intelligence","pct":98},{"name":"Streetwise","pct":74},{"name":"Interrogation Techniques","pct":87},{"name":"Wilderness Survival","pct":77},{"name":"Land Navigation","pct":74},{"name":"Literacy: English","pct":87},{"name":"Basic Math","pct":90}]', 'Climbing is printed 97%/92% (second figure is the rappelling figure). Body Building, Gymnastics and General Athletics have no percentage. W.P. Energy Pistol, W.P. Energy Rifle, W.P. Bolt-Action Rifle, W.P. Knife, W.P. Sniper. Hand to Hand: Expert (CS Officer).', NULL, 'None.', 'None.', NULL, 'Left hand is a bio-system prosthetic replacing one lost early in his career; gyro-compass, clock calendar, fingerjack, amplified hearing, sound filtration system, one multi-optic eye.', 'Favorite weapons: neural mace, vibro-knife, C-14 "Fire Breather", C-50 "Dragonfire", CV-212 variable light frequency laser rifle and similar precision sniper weapons. No damage figures printed.', NULL, 'Steady, self-assured, fair and compassionate; he puts his troops'' welfare just below that of the Coalition itself. A career soldier who dislikes politics, resents second-guessing, and quietly bends rules to spare D-Bees and his men.', NULL, NULL, 'Haim is the veteran Coalition officer who runs Fort Barron, the large intelligence base on the edge of Xiticix territory. He turned down promotions to keep the post and is among the CS''s foremost authorities on the Xiticix. Psi-Stalkers and many D-Bees respect him, and his troops are devoted to him.', 'Rifts World Book 23: Xiticix Invasion p.144-145'),
('orion-greenfeld', 'Orion Greenfeld', NULL, 'Trapper-Woodsman, hired scout for the Coalition', 'rifts', 'Human', '11th level Trapper-Woodsman', 11, 'Unprincipled', 'Claims to be 50 (but looks sixty or seventy)', 'Six feet, two inches (1.88 m)', '168 lbs (75.6 kg)', '{"IQ":14,"ME":15,"MA":24,"PS":21,"PP":20,"PE":17,"PB":10,"Spd":22}', 53, 30, NULL, 9, NULL, NULL, NULL, '{"attacks":6,"initiative":2,"strike":4,"parry":5,"dodge":5,"roll":2,"pull":5,"damage":6}', 'Damage bonus is S.D.C. damage from P.S. Critical strike on natural 18-20, judo body throw, paired weapons, +1 to save vs possession, +2 to save vs poison and disease, +2 to save vs cold and pain, +6 to save vs Horror Factor, 80% likelihood of evoking trust or intimidation. Hand to Hand: Expert.', '[{"name":"Basic Math","pct":90},{"name":"Speak English/American","pct":92},{"name":"Speak Inuit and Euro","pct":98},{"name":"Lore: Demon & Monsters","pct":95},{"name":"Lore: Animals","pct":98},{"name":"Animal Husbandry","pct":98},{"name":"Climbing","pct":95},{"name":"Swimming","pct":98},{"name":"Pilot Hovercycle","pct":90},{"name":"Pilot Sail Boat","pct":98},{"name":"Radio Basic","pct":98},{"name":"Wilderness Survival","pct":98},{"name":"Land Navigation","pct":98},{"name":"Cardsharp","pct":68},{"name":"Palming","pct":75},{"name":"Prowl","pct":85}]', 'Climbing printed 95%/90%. Illiterate (cannot read or write). Printed with bonuses only: Track Animals (+20%), Skin & Prepare Animal Hides (+25%), I.D. Plants & Fruits (+15%), Trap/Mine Detection (+10%). No percentage: Hunting, Fishing, General Athletics, Running, Trap Construction. W.P. Energy Rifle, W.P. Bolt-Action Rifle, W.P. Knife, W.P. Blunt. Hand to Hand: Expert.', NULL, 'Lore only (Magic Knowledge: Lore only).', 'None.', NULL, 'None.', 'Bolt-action hunting rifle (6D6 S.D.C.); .45 automatic pistol (4D6 S.D.C.); vibro-knife; Wilk''s 237 "Backup" Laser Pistol (3D6 or 6D6 M.D. per double blast; 500 feet/152 m range); C-50 "Dragonfire" assault rifle and grenade launcher (a CS gift); Wilk''s Laser Lance for skinning hides. Six long E-Clips for each energy weapon, 144 rounds for each S.D.C. gun, 32 grenades for the C-50, four flares, two smoke grenades. Armor: modified non-environmental (no helmet) "Dead Boy" armor, 69 M.D.C., painted greens and grays, a gift from Major Haim; also owns a suit of Urban Warrior armor.', NULL, 'Friendly, talkative and confident, and fond of his own celebrity; he spins embellished stories at length. He is rough-edged and ornery when provoked, rarely swears, does not drink, and looks out for himself first.', NULL, NULL, 'Orion is an eccentric veteran woodsman who scouts for the Coalition and has worked for Major Haim at Fort Barron for ten years. Known and trusted by nearly every Psi-Stalker tribe and many Native Americans, he is something of a legend among scouts and trappers. His knowledge of Manitoba, Ontario and the upper Midwest is real despite his tall tales.', 'Rifts World Book 23: Xiticix Invasion p.145-147'),
('commander-jess-helgeland', 'Commander Jess Helgeland', NULL, 'Commander, leader of the Wild Pack; Coalition Psi-Stalker', 'rifts', 'Human', '10th level Coalition Psi-Stalker', 10, 'Principled', '30', '5 feet, 11 inches (1.8 m)', '150 lbs (68.1 kg)', '{"IQ":14,"ME":18,"MA":18,"PS":20,"PP":20,"PE":20,"PB":20,"Spd":32}', 69, 60, NULL, 12, 178, NULL, NULL, '{"attacks":7,"strike":5,"parry":8,"dodge":8,"roll":4,"pull":2,"damage":8}', '+3 to save vs magic & poison, +10% to save vs coma/death. Critical Strike natural 18-20, Paired Weapons (All), Body Throw/Flip 1D6+8 plus victim loses one attack and initiative, Knockout/Stun natural 20, Body Block/Tackle 1D4+8, Pin/Incapacitate 18-20, Crush/Squeeze 1D4+8. Hand to Hand: Expert.', '[]', 'No absolute percentages printed; bonuses only: Radio: Basic (+10%), Pilot Hovercraft (+10%), Read Sensory Equipment (+10%), Weapon Systems (+10%), Climbing (+15%), Prowl (+10%). No percentage: Robot Combat: Basic, Body Building, Running, Boxing, Swimming, Wrestling, Navigation, First Aid, Basic Electronics, Computer Operation, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons, W.P. Heavy (printed that way, truncated).', 'Psi-Stalker senses: detects psychic and magic energy, senses supernatural beings, and has psionic empathy with animals.', 'None printed.', 'Astral Projection (8), Clairvoyance (4), Sense Evil (2), Telepathy (4), See Aura (6), Object Read (6). I.S.P. 178.', NULL, 'None printed.', 'CP-50 Dragonfire Assault Rifle & Grenade Launcher (2D6 M.D. per single shot; grenade launcher 6D6 M.D., 12 foot/3.6 m diameter blast area); CP-30 Laser Pulse Pistol (no damage printed); Vibro-Saber (2D6 M.D.); 10 long E-Clips, 9 standard E-Clips, 14 micro-fusion grenades in a crossover bandoleer. Body armor: CA-4 Standard "Dead Boy" Armor (100 M.D.C. main body). Standard starting equipment plus an NGS2 Basic Survival Pack.', NULL, 'Weathered, tough and unyielding, worn down by long service in the Hivelands; she can no longer relax out of crisis mode and would likely go mad in a quiet life. Beneath that she is warm and caring, though few see it now.', 'Her Dog Boy team (Sgt. Samuel, Corp. Chase, Corp. Chesterfield); recent associates are two Spider Tribe Psi-Stalkers and the feral Dog Boy Crunch.', 'The Xiticix', 'Helgeland is a Coalition Psi-Stalker and fugitive hunter who led a Dog Boy team after the D-Bee Grulka Sdetla into Xiticix territory. After losing three Dog Boys, her team stayed behind to fight the Xiticix and called themselves the Wild Pack. She commands that fire-team and officially still reports hunting Sdetla.', 'Rifts World Book 23: Xiticix Invasion p.153-154'),
('sgt-samuel', 'Sgt. Samuel', NULL, 'Dog Boy, The Wild Pack', 'rifts', 'Bloodhound Dog Boy', '6th level Dog Boy', 6, 'Principled', '5', '5 feet, 10 inches (1.78 m)', '170 lbs (77.2 kg)', '{"IQ":15,"ME":15,"MA":15,"PS":20,"PP":25,"PE":20,"PB":15,"Spd":32}', 44, 50, NULL, 10, 125, NULL, NULL, '{"attacks":5,"initiative":2,"strike":8,"parry":9,"dodge":9,"roll":3,"pull":3,"damage":5}', 'Base save vs psionics 10, +1 to save vs psionic attacks. Also: Jump Kick, Entangle, Critical Strike natural 18-20. Hand to Hand: Martial Arts.', '[]', 'No absolute percentages printed; bonuses only: Intelligence (+10%), Radio: Basic (+10%), Pilot Hovercraft (+10%), Read Sensory Equipment (+10%), Weapon Systems (+10%), Climbing (+10%), Land Navigation (+10%), Wilderness Survival (+10%). No percentage: Radio: Scramblers, Pilot Jet Pack, Running, Prowl, Detect Ambush, Intelligence (listed twice), W.P. Energy Pistol, W.P. Energy Rifle, W.P. Paired Weapons. Hand to Hand: Martial Arts.', 'Bloodhound traits: detects psychic and magical energy and supernatural beings, superior sense of smell with +12% to tracking by smell, keen hearing, swims at 45%.', 'None printed.', 'Sense Evil (2), Sense Magic (3), Sixth Sense (2), Empathy (4), See Aura (6). I.S.P. 125.', NULL, 'None printed.', 'CP-50 Dragonfire Assault Rifle & Grenade Launcher (2D6 M.D. per single shot; grenade launcher 6D6 M.D., 12 foot/3.6 m diameter blast area); CP-30 Laser Pulse Pistol (2D4 M.D.); pair of Vibro-Swords (long sword 3D6 M.D., short sword 2D6 M.D.), always used as a paired unit. Extra ammo: 14 long E-Clips, 8 standard E-Clips, 19 micro-fusion grenades in a crossover bandoleer. Body armor: Standard CA-4 "Dead Boy" Armor (100 M.D.C. main body). Standard starting equipment plus an NGS2 Basic Survival Pack.', NULL, 'Quiet, thoughtful and intense; a silent, remorseless killer who is also the most dependable and selfless of the Wild Pack''s Dog Boys, a true crusader.', 'The rest of the Wild Pack, led by Commander Jess Helgeland', 'The Xiticix', 'Samuel is a Bloodhound Dog Boy sergeant and the steadiest member of Helgeland''s Wild Pack. He fights as a quiet blade-wielding killer in the dark against the Xiticix.', 'Rifts World Book 23: Xiticix Invasion p.154'),
('corp-chase', 'Corp. Chase', NULL, 'Dog Boy, The Wild Pack', 'rifts', 'Boxer Dog Boy', '6th level Dog Boy', 6, 'Unprincipled', '6', '6 feet (1.83 m)', '200 lbs (91 kg)', '{"IQ":15,"ME":13,"MA":15,"PS":25,"PP":20,"PE":20,"PB":15,"Spd":30}', 50, 44, NULL, 10, 125, NULL, NULL, '{"attacks":5,"initiative":2,"strike":6,"parry":7,"dodge":7,"roll":3,"pull":3,"damage":10}', 'Base save vs psionics 10, +1 to save vs psionic attacks. Also: Jump Kick, Entangle, Critical Strike natural 18-20. Hand to Hand: Martial Arts.', '[]', 'No absolute percentages printed; bonuses only: Intelligence (+10%), Radio: Basic (+10%), Pilot Hovercraft (+10%), Read Sensory Equipment (+10%), Weapon Systems (+10%), Climbing (+10%), Land Navigation (+10%), Wilderness Survival (+10%). No percentage: Radio: Scrambler, Pilot Jet Pack, Running, Weapon Engineer, Mechanical Engineer, Robot Mechanics, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons. Hand to Hand: Martial Arts.', 'Boxer traits: superior sense of smell with +4% to track by smell, keen hearing, can leap 15 feet/4.6 m high from a quick running start.', 'None printed.', 'Sense Evil (2), Sense Magic (3), Sixth Sense (2), Empathy (4), Astral Projection (8). I.S.P. 125.', NULL, 'None printed.', 'CP-50 Dragonfire Assault Rifle & Grenade Launcher (2D6 M.D. per single shot; grenade launcher 6D6 M.D., 12 foot/3.6 m diameter blast area); CP-30 Laser Pulse Pistol (no damage printed); Vibro-Saber (2D6 M.D.); 14 long E-Clips, 20 standard E-Clips, 40 micro-fusion grenades in a crossover bandoleer and two satchels. Body armor: Standard "Dog Boy" Armor (50 M.D.C., main body). Standard starting equipment plus an NGS2 Basic Survival Pack.', NULL, 'Impulsive; his wild streak makes him slip away to fight alone, so teammates must rescue him, which leaves him ashamed. He cannot seem to help it.', 'The rest of the Wild Pack, led by Commander Jess Helgeland', 'The Xiticix', 'Chase is a hard-hitting Boxer Dog Boy in the Wild Pack, whose rash solo attacks on the Xiticix keep his team pulling him out of trouble.', 'Rifts World Book 23: Xiticix Invasion p.154'),
('corp-chesterfield', 'Corp. Chesterfield', NULL, 'Dog Boy, The Wild Pack', 'rifts', 'Lakeland Terrier Dog Boy', '6th level Dog Boy', 6, 'Principled', '6', '4 feet, 6 inches (1.4 m)', '110 lbs (50 kg)', '{"IQ":15,"ME":13,"MA":15,"PS":20,"PP":21,"PE":25,"PB":15,"Spd":36}', 60, 44, NULL, 10, 125, NULL, NULL, '{"attacks":5,"initiative":2,"strike":6,"parry":7,"dodge":7,"roll":3,"pull":3,"damage":5}', 'Special abilities also list +2 to initiative and +1 to strike (Combat Bonuses repeat +2 initiative and give +6 strike). Base save vs psionics 10, +1 to save vs psionics, +5 to save vs magic & poison, +20% to save vs coma/death. Also: Jump Kick, Entangle, Critical Strike natural 18-20. Hand to Hand: Martial Arts.', '[]', 'No absolute percentages printed; bonuses only: Intelligence (+10%), Radio: Basic (+10%), Pilot Hovercraft (+10%), Read Sensory Equipment (+10%), Weapon Systems (+10%), Climbing (+10%), Land Navigation (+10%), Wilderness Survival (+10%). No percentage: Radio: Scramblers, Cryptography, Pilot Jet Pack, Running, Pilot Robots and Power Armor, Navigation, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons. Hand to Hand: Martial Arts.', 'Terrier traits: a superior nose and sharp hearing; an aggressive, hardy breed; swims at 40%. Special abilities also print +2D6 S.D.C.', 'None printed.', 'Sense Evil (2), Sense Magic (3), Sixth Sense (2), Empathy (4), See the Invisible (4). I.S.P. 125.', NULL, 'None printed.', 'C-27 "Light" Plasma Cannon (6D6 M.D. per blast; rate of fire equal to attacks per melee round; range 1,600 feet (printed as 488 km); payload 10 shots per energy canister; +1 to strike); CP-50 Dragonfire Assault Rifle & Grenade Launcher (2D6 M.D. per single shot; grenade launcher 6D6 M.D., 12 foot/3.6 m diameter blast area); pair of Vibro-Claws (2D4 M.D.); Xiticix resin dagger (1D4 M.D.); six C-27 energy canisters, 8 long E-Clips, 8 standard E-Clips, 10 micro-fusion grenades in a large belt pouch. Body armor: Standard "Dog Boy" Armor (50 M.D.C., main body). Standard starting equipment.', NULL, 'Tired of the endless Xiticix war and drawn to robot vehicles and heavy weapons, he dreams of leaving as an adventurer but cannot imagine life apart from the Pack he grew up with. The conflict could tear him apart.', 'The rest of the Wild Pack, led by Commander Jess Helgeland', 'The Xiticix', 'Chesterfield is a small, tough Lakeland Terrier Dog Boy corporal who carries the Wild Pack''s plasma cannon. He is torn between loyalty to the Pack and a longing to leave the Hivelands.', 'Rifts World Book 23: Xiticix Invasion p.154-155'),
('the-mighty-cassandra', 'The Mighty Cassandra', NULL, 'Hyperion Juicer of Manitoba & Company', 'rifts', 'Human', '6th level Hyperion Juicer', 6, 'Anarchist', '19', '5 feet, 6 inches (1.67 m)', '140 lbs (63.6 kg)', '{"IQ":9,"ME":8,"MA":8,"PS":25,"PP":25,"PE":30,"PB":20,"Spd":150}', 50, 180, NULL, NULL, NULL, NULL, NULL, '{"attacks":7,"initiative":6,"strike":9,"parry":8,"dodge":9,"roll":4}', '+4 to save vs psionics, +4 to save vs mind control, +9 to save vs disease, toxic gases and other poisons. Spd 150 is printed with the note approx. 103 mph/165 km. Kick 3D6 S.D.C.; Power Kick 1D6 M.D. (counts as two attacks); Automatic Parry; Automatic Dodge. Vibro-Spike Armor Slam 2D6 M.D., Power Slam 4D6 M.D. (counts as two attacks).', '[]', 'No absolute percentages printed; bonuses only: Acrobatics (+5%), Climbing (+5%), Gymnastics (+5%), Land Navigation (+15%), Radio: Basic (+10%), Wilderness Survival (+10%). Without a figure: W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons, W.P. Sword, W.P. Knife, Swimming, Prowl, First Aid, Pilot Jet Pack, Pilot Hover Craft, Pilot Tanks & APCs, Pilot Truck. Hand to Hand: Martial Arts.', 'Hyperion Juicer augmentation gives her extreme speed and endurance; the book says she is roughly 12 to 16 months from burning out.', 'None.', 'None.', NULL, 'None.', 'WI-CL8 Multi-Purpose Weapon System: Chainsaw 5D6 M.D. (hand to hand only), Laser 3D6 M.D., range 2,000 feet (610 m) for the laser; R.O.F. equal to hand to hand attacks per round; payload requires two E-Clips, laser has 20 shots, second E-Clip runs the chainsaw one hour continuous (each activation drains at least one minute); -1 to strike (awkward balance). Extra ammo: 12 extra E-Clips in web belt pouches. Body armor: Vibro-Spike Armor, 50 M.D.C. (Slam 2D6 M.D., Power Slam 4D6 M.D. counts as two attacks). Other: standard Hyperion Juicer starting equipment.', 'None; she spends it as fast as she gets it.', 'Hyper and vain, certain she is better than everyone around her. She lives for the moment, knowing the Juicer burn-out is close, and is happy to burn bright until then.', 'Manitoba & Company (Manitoba Saskatchewan, Hidechek Gezenske, Dekker Trons''stedaal)', NULL, 'A young Hyperion Juicer in the mercenary crew Manitoba & Company, which the Coalition keeps on semi-permanent retainer to harass the Xiticix and spy on traffic around Lazlo. Her stat block opens on printed page 155 and finishes on 156.', 'Rifts World Book 23: Xiticix Invasion p.155-156'),
('hidechek-gezenske', 'Hidechek Gezenske', NULL, 'Notorious Burster; original leader of the crew', 'rifts', 'Human', '12th level Burster', 12, 'Anarchist', '36', '6 feet (1.83 m)', '160 lbs (72.6 kg)', '{"IQ":10,"ME":20,"MA":10,"PS":14,"PP":14,"PE":14,"PB":9,"Spd":13}', 58, 40, NULL, 10, 250, NULL, NULL, '{"attacks":6,"strike":2,"parry":3,"dodge":3,"damage":2,"pull":4,"roll":4}', 'Critical Strike on Natural 19-20. Kick 1D6 S.D.C. Fire Bolt 2D6/4D6/6D6 M.D. Body Throw/Flip 1D6 plus victim loses one attack and initiative. -2 to strike with the Naruni NE-4 (not strong enough to brace it).', '[]', 'No absolute percentages printed; bonuses only: Pilot Motorcycle (+10%), Pilot Tanks & APCs (+10%). Without a figure: Wilderness Survival, Body Building, Swimming, Climbing, Prowl, First Aid, Basic Mechanics, Basic Electronics, W.P. Energy Pistol, W.P. Energy Rifle. Hand to Hand: Basic.', NULL, 'None.', 'Impervious to Fire and Heat, Extinguish Fires (4), Flame Burst (4), Fire Bolt (2 or 4), Fire Eruption, Sense Fire (2), Super Fuel Flame (8), Levitation, Resist Thirst (6), Resist Hunger (2). I.S.P. 250.', NULL, 'None.', 'Naruni NE-4 Plasma Cartridge Pistol: 1D4x10 M.D. per shot, R.O.F. equal to hand to hand attacks, range 500 feet (152 m), 10 round magazine; -2 to strike. Vibro Blade 3D6 M.D. Three NE-4 magazines (running low). Body armor: patched Bushman armor, 52 M.D.C. Other: standard starting equipment for a Burster.', 'About 5,000 credits of salable black-market goods (contraband music, vintage whiskey, a laser disc of Super Bowl #50) plus about 1,000 credits in gold.', 'Pompous and irritating, because he once led this crew. He saves his scarce plasma pistol ammo for when he truly needs it.', 'Manitoba & Company', NULL, 'A veteran Burster who started the mercenary crew that Manitoba & Company grew from. He is the fire-wielding psychic of the group, with a high I.S.P. pool and a prized Naruni plasma pistol he cannot quite handle.', 'Rifts World Book 23: Xiticix Invasion p.156'),
('manitoba-saskatchewan', 'Manitoba Saskatchewan', NULL, 'Gunfighter of Manitoba & Company', 'rifts', 'Greot Hunter', '9th level Gunfighter', 9, 'Miscreant', '25', '8 feet (2.4 m)', '600 lbs (270 kg)', '{"IQ":6,"ME":8,"MA":7,"PS":35,"PP":15,"PE":20,"PB":3,"Spd":15}', NULL, NULL, 196, 3, NULL, NULL, 12, '{"attacks":5,"disarm":3}', 'Spd 15 on land, 45 when swimming. Attacks per melee: five, +1 with guns, and a sharpshooter with pistols. +3 to disarm on a called shot, +5 to save vs Horror Factor, +1 to save vs magic, +1 to save vs possession, +3 to save vs poison, +5 to save vs disease. W.P. Sword +3 to strike, +3 to parry. Wilk''s 237 pistols +2 to strike. Reputation/Horror Factor 12.', '[]', 'No absolute percentages printed; bonuses only: Land Navigation (+10%), Detect Ambush (+15%), Detect Concealment (+10%), Find Contraband (+12%), Recognize Weapon Quality (+20%), Basic Electronics (+10%), Armorer (+20%), Escape Artist (+5%), Tracking (+5%), Interrogation (+5%). Without a figure: Sniper, W.P. Revolver, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons, W.P. Sword, Pilot: Tanks & APCs, Horsemanship: Exotic, First Aid, Basic Mechanics, Locksmith, Climb, Prowl. Special abilities: Weapons Master, Weapon Repairs, Paired Weapons: Pistols, W.P. Sharpshooting: Energy Pistol. Hand to Hand: Expert. The skills list runs across printed 157 and 158.', 'Keen eyesight, a natural swimmer (98%), and regenerates 3D6 M.D.C. every 12 hours.', 'None.', 'None.', NULL, 'None.', 'Wilk''s 237 "Backup" (6 pistols, fired in pairs): 3D6 M.D. per single blast or 6D6 per double blast, R.O.F. equal to hand to hand attacks, range 500 feet (152 m), 16 single pulse shots or 8 double pulse shots per standard E-Clip, +2 to strike; he never uses single-pulse. Wilk''s-Remi 157 "Judgement Day" rifle: 3D6+2 per single shot or 1D6x10 per three-shot burst, range 1,800 feet (548.6 m), 30 single shots or 10 triple pulse shots per long E-Clip. Extra ammo: 18 standard E-Clips and five long E-Clips in a satchel (he sometimes grabs the wrong clip). Body armor: none (he refuses it). Other equipment: none to speak of.', 'None; he wastes or loses whatever he earns and is easily swindled.', 'A dim, hot-tempered brute who hates both Xiticix and everyone else. He lurks on the Hivelands border, apparently building up nerve to go in after a legendary artifact called the Codex of Souls, and is close to snapping at his human crewmates.', 'Manitoba & Company (reluctantly)', 'Xiticix; humans generally', 'The Greot Hunter gunfighter whose behavior strains the mercenary crew Manitoba & Company, named for the regions he roamed. He is a heavy, pistol-twirling M.D.C. brute whose block starts on printed 156, runs across a full-page illustration on 157, and ends on 158.', 'Rifts World Book 23: Xiticix Invasion p.156-158'),
('dekker-tronsstedaal', 'Dekker Trons''stedaal', NULL, 'AWOL Coalition Military Specialist piloting a retrofitted Mauler', 'rifts', 'Human', '4th level CS Elite RPA (Robot & Power Armor) Pilot', 4, 'Miscreant', '22', '5 feet, 10 inches (1.78 m)', '160 lbs (72.6 kg)', '{"IQ":14,"ME":14,"MA":12,"PS":10,"PP":13,"PE":13,"PB":10,"Spd":20}', 40, 50, NULL, NULL, NULL, NULL, NULL, '{"attacks":6,"strike":2,"parry":5,"dodge":5,"roll":3}', 'Attacks per melee: six, eight in his power armor. Power Armor Combat Bonuses (in addition to normal): +2 attacks per melee, +2 to strike, +2 to parry, +2 to dodge on ground, +5 to dodge while flying (if applicable), +3 to roll with punch/fall/impact, critical strike; punch 1D6 M.D., kick 1D6 M.D., leap kick 2D6 M.D. (counts as two attacks), body flip/throw 1D4 M.D., body block/tackle 1D6 M.D. (counts as two attacks). Mauler hand to hand is Basic Power Armor Combat Training (Rifts RPG p.45).', '[]', 'No absolute percentages printed; bonuses only: Radio: Basic (+10%), Pilot Automobile (+10%), Pilot Hovercraft (+10%), Pilot Tank & APCs (+15%), Pilot Robots and Power Armor (+10%), Pilot Jet Packs (+10%), Navigation (+10%), Read Sensory Equipment (+15%), Weapon Systems (+15%). Without a figure: Radio: Scrambler, Robot Combat: Elite, Running, Climbing, Body Building & Weight Lifting, Boxing, Wrestling, Wilderness Survival, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons. Hand to Hand: Expert, Power Armor Elite Combat Training.', NULL, 'None.', 'None.', NULL, 'None.', 'CP-40 Pulse Laser Rifle (2D6 M.D. single blast or 6D6 triple blast), C-20 Laser Pistol (2D6 M.D.), survival knife (1D6 S.D.C.), 16 long E-Clips. Body armor: standard CA-4 "Dead Boy" Armor, 100 M.D.C. main body. MAULER POWER ARMOR (about half its M.D.C. left; quick stats): Crew one. M.D.C. by location: Hands (2) 25 each; Arms (2) 100 each; Legs (2) 150 each; Plasma Shoulder Guns (2) 65 each; Concealed Mini-Missile Launcher (1, back) 50; Concealed Forearm Blasters (2) 50 each; Retractable Vibro-Sabers (2) 50 each; Rear Jet Thruster (1) 50; Shoulder Thruster Units (2) 30 each; Maneuvering Jets (8) 15 each; Mini-Lights (6) 1 each; Head 90; Main Body 280. Hands, Maneuvering Jets and Mini-Lights are small, difficult targets (called shot at -4). Destroying the head eliminates optical and sensory systems; the pilot uses own senses and all power armor strike/parry/dodge bonuses are lost; called shot at -4. Depleting the main body shuts the armor down. Speed: running 40 mph/64 kph, leaping 15 feet (4.6 m), underwater 15 mph (24 km). Height 8 feet (2.4 m), width 4.5 feet (1.4 m), length 4 feet (1.2 m), weight 1,800 lbs (810 kg), P.S. equal to 36, cargo none, nuclear power with average life span 20 years. Armor weapons: Shoulder Plasma Ejectors (2) 4D6 M.D., range 1,200 feet (365.7 m), each fires twice per melee, effectively unlimited payload; Concealed Back-Mounted Mini-Missile Launcher (1) 1D4x10 M.D. (fragmentation), range one mile (1.6 km), single shot or volleys of two or three, payload eight; Forearm Lasers (2) 2D6 M.D., range 1,200 feet (366 m), R.O.F. equal to the combined hand to hand attacks of the pilot, effectively unlimited payload; Retractable Forearm Vibro-Sabers (2) 2D4 M.D., +1 to strike and parry.', NULL, 'A deserter who abandoned his Coalition scouting unit to die when Xiticix ambushed it, then fell in with these marauders. He does not mind being a fugitive and is unlikely to return home, since a large bounty hangs over him for taking a costly suit of armor.', 'Manitoba & Company', 'Coalition States (bounty on his head)', 'The Coalition deserter of Manitoba & Company, flying a half-damaged Mauler power armor. His block begins on printed 158 and the Mauler quick stats and weapons run onto the top of 159.', 'Rifts World Book 23: Xiticix Invasion p.158-159'),
('serian-skeld', 'Serian Skeld', NULL, 'Fire Dragon Hatchling of The Lazlo Triad', 'rifts', 'Fire Dragon Hatchling', '5th level Fire Dragon Hatchling', 5, 'Unprincipled', 'One year, three months', '20 to 30 feet (6-9 m) tall, up to 65 feet (20 m) long, wingspan 100 feet (30.5 m) (printed as Size)', '25 tons', '{"IQ":22,"ME":19,"MA":23,"PS":26,"PP":19,"PE":22,"PB":24,"Spd":21}', NULL, NULL, 400, 80, 60, NULL, 12, '{"attacks":6,"strike":3,"parry":3,"dodge":3,"damage":13,"pull":2,"roll":2}', 'All figures and the 400 M.D.C. are the true dragon form; the book also says she usually passes as a simple human traveler and drops the disguise at the first sign of trouble, but prints no separate human-guise stats. Attacks per melee: six hand to hand or two via spell magic. Combat training equal to Hand to Hand: Basic. +2 to save vs psionic attack, +4 to save vs magic, +4 to save vs poison and disease, 70% to charm and impress, 75% to evoke trust. Fire breath 6D6 M.D. P.S. is Supernatural for punching, clawing, kicking damage. Critical Strike: Natural 19-20. Bio-regenerates 1D4x10 M.D. every five minutes. Teleport 36%. Fly 50 mph (80 km). Nightvision 90 feet (27.4 m).', '[{"name":"Basic & Advanced Math","pct":98},{"name":"Demon and Monster Lore","pct":90},{"name":"Faerie Lore","pct":40},{"name":"Basic Electronics","pct":92},{"name":"Computer Operation","pct":92}]', 'Also: Climbing, Swimming, Art, Writing, Sing, Dance, W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy Weapons, Pilot Hover Craft.', 'Flies, sees in the dark and sees the invisible, is immune to fire, heals quickly, can change shape (metamorphosis), and can teleport. Her fire breath and supernatural strength are her main attacks.', 'Blinding Flash (1), Cloud of Smoke (2), Latern Light (1) [printed spelling], Cleanse (6), Throwing Stones (5), Fuel Flame (5), Fool''s Gold (10), Armor of Ithan (10), Invisibility: Simple (6), Carpet of Adhesion (10), Ley Line Transmission (30), Tongues (12), Domination (10), Eyes of Thoth (8). P.P.E. 80.', 'Astral Projection (8), See Aura (6), Telekinesis (varies), Mind Block (4), Healing Touch (10), Presence Sense (4). I.S.P. 60.', NULL, 'None.', 'Weapons: none. Body armor: none. Other equipment: none beyond what she carries to keep up her human traveler cover.', 'Not much yet; she is building a personal hoard worth about 20,000 credits after being talked into donating earlier earnings to Lazlo.', 'Brash and impulsive, still very young. She means well but is a liability until she grows up, which is why she has been paired with Sir Jericho Camlann to give her direction.', 'The Lazlo Triad; Sir Jericho Camlann', 'Xiticix', 'The dragon hatchling who is one of the three leaders of The Lazlo Triad, a band of crusaders from Lazlo set against the Xiticix. She travels as a human and transforms into her dragon body when danger appears.', 'Rifts World Book 23: Xiticix Invasion p.159'),
('sir-jericho-camlann', 'Sir Jericho Camlann', NULL, 'Cyber-Knight of The Lazlo Triad', 'rifts', 'Human', '9th level Cyber-Knight', 9, 'Scrupulous', '31', '5 feet, 11 inches (1.8 m)', '200 lbs (90 kg)', '{"IQ":15,"ME":18,"MA":20,"PS":22,"PP":22,"PE":20,"PB":15,"Spd":23}', 65, 110, NULL, 30, 72, 16, NULL, '{"attacks":8,"initiative":1,"strike":6,"parry":9,"dodge":9,"damage":7,"pull":3,"roll":9}', '+2 to save vs psychic attack and insanity, +3 to save vs poison and magic, +10% to save vs coma/death. Karate Kick 1D8, Jump Kick, Entangle, Critical Strike Natural 18-20, W.P. Paired Weapons (All), Leap Attack (Critical Strike), Pin/Incapacitate 18-20, Crush/Squeeze 1D4+7. W.P. Sword +3 to strike and parry; W.P. Knife +2 to strike, +3 to parry, +2 to throw. Karate Kick damage printed as IDS in the cache text; the render shows 1D8.', '[]', 'No absolute percentages printed; bonuses only: Literacy (+20%), Lore: Demon (+20%), Anthropology (+15%), Paramedic (+10%), Land Navigation (+12%), Horsemanship (+15%), Climbing (+10%), Gymnastics (+5%), Swimming (+10%), Acrobatics (+5%), Play Musical Instrument (+5%), Dance (+5%), Wilderness Survival (+5%), Hunting (+5%), Identify Plants & Fruits (+5%), Preserve Food (+5%), Skin & Prepare Animal Hides (+5%), Track Animals (+5%), Lore: Faerie (+5%), Tracking (+5%). Without a figure: Body Building, Boxing, Wrestling, W.P. Sword, W.P. Knife, W.P. Energy Pistol, W.P. Energy Rifle. Hand to Hand: Martial Arts.', NULL, 'None.', 'Summon Inner Strength, Sixth Sense, Sense Evil. Special ability: Psi-Sword 4D6 M.D. I.S.P. 72.', NULL, 'Cyber-Armor: A.R. 16, M.D.C. 50 (a suit of Crusader Armor, 55 M.D.C., is worn over it).', 'NG-P7 Particle Beam Rifle (1D4x10 M.D. per blast, range 1,200 feet/365 m), a pair of NG-57 Heavy-Duty Ion Blasters (2D4 or 3D6 M.D., range 500 feet/152 m), 10 E-Clips for each. Silver Holy Sword (maybe a rune sword): 4D6 M.D. per strike, apparently indestructible, flies to his hand from up to one mile (1.6 km). Body armor: Crusader Armor 55 M.D.C. over Cyber-Armor 50 M.D.C. (A.R. 16). Other: standard Cyber-Knight gear plus a bundle of daggers taken from defeated foes (one belonged to the Shifter Deraalzebun, another to an anonymous Mystic Knight).', 'Keeps only the few credits he needs; sends other proceeds to the Lazlo city government for defense and charity.', 'Honorable and soft-spoken; he serves as the moral guide of the group and tends to say little but clarify a lot.', 'The Lazlo Triad; Serian Skeld; Omicron; the city of Lazlo', 'Xiticix', 'The Cyber-Knight co-leader of The Lazlo Triad and mentor to the young dragon Serian Skeld. His block starts at the bottom of printed 159 and ends on 160.', 'Rifts World Book 23: Xiticix Invasion p.159-160'),
('omicron-lazlo-triad', 'Omicron', NULL, 'Ley Line Walker of The Lazlo Triad', 'rifts', 'Human', '5th level Ley Line Walker', 5, 'Principled', '23', '6 feet, 1 inch (1.85 m)', '140 lbs (63.6 kg)', '{"IQ":15,"ME":20,"MA":9,"PS":12,"PP":13,"PE":10,"PB":13,"Spd":16}', 29, 18, NULL, 115, NULL, NULL, NULL, '{"attacks":5,"strike":1,"parry":2,"dodge":2,"pull":2,"roll":2}', 'Attacks per melee: five hand to hand or two via magic. +3 to save vs psychic attack & insanity. Kick 1D6. Gladiator armor halves his Speed.', '[]', 'No absolute percentages printed; bonuses only: Climbing (+5%), Land Navigation (+4%), Wilderness Survival (+5%), Pilot Hover Craft (+5%), Lore: Demon (+10%), Math: Basic (+10%), Radio: Basic (+10%), Intelligence (+5%), First Aid (+5%), Paramedic (+5%). Without a figure: Art, Writing, W.P. Energy Pistol, W.P. Sword, W.P. Knife. Hand to Hand: Basic.', 'Standard Ley Line Walker abilities: senses ley lines and magic energy, reads ley lines, ley line transmission, phasing, drifting, rejuvenation and the observation ball.', 'Blinding Flash (1), Cloud of Smoke (2), Death Trance (1), Globe of Daylight (2), Befuddle (3), Chameleon (6), Climb (3), Concealment (6), Armor of Ithan (10), Breathe Without Air (5), Energy Bolt (5), Fingers of Wind (5), Astral Projection (10), Carpet of Adhesion (10), Blind (6), Charismatic Aura (10), Circle of Flame (10). P.P.E. 115.', 'None.', NULL, 'None.', 'Wilk''s 320 Laser Pistol (1D6 M.D., range 1,000 feet/305 m). Body armor: The Gladiator, 70 M.D.C. (halves his Speed). Other: standard Ley Line Walker gear plus a sealed metal book with brass-plate pages, nearly 50 lbs (22.7 kg), which he cannot open.', 'Roughly 5,000 credits on him and a large stash back in Lazlo; Sir Jericho is persuading him to donate it.', 'A bookish, awkward wizard with a good heart who is fully devoted to stopping the Xiticix. He hopes to find magic that could banish them to another world.', 'The Lazlo Triad; Sir Jericho Camlann; Serian Skeld', 'Xiticix', 'The Ley Line Walker, third core leader of The Lazlo Triad, who supplies the group''s spellcasting. His block appears on printed 160 and ends the Lazlo Triad entries in this slice.', 'Rifts World Book 23: Xiticix Invasion p.160');
