-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 21 notable NPCs are in' AS assertion, count(*) AS got, 21 AS want
  FROM notable_npcs WHERE slug IN ('quiwan-li', 'brok-magnil', 'raskin-free-thinker', 'illyana-free-thinker', 'cristobal-free-thinker', 'summers-free-thinker', 'typical-dead-boy-commando-durango', 'typical-cs-elite-rpa-pilot-durango', 'major-samuel-haim', 'orion-greenfeld', 'commander-jess-helgeland', 'sgt-samuel', 'corp-chase', 'corp-chesterfield', 'the-mighty-cassandra', 'hidechek-gezenske', 'manitoba-saskatchewan', 'dekker-tronsstedaal', 'serian-skeld', 'sir-jericho-camlann', 'omicron-lazlo-triad');
SELECT 'and the notables 92' AS assertion, count(*) AS got, 92 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('quiwan-li', 'brok-magnil', 'raskin-free-thinker', 'illyana-free-thinker', 'cristobal-free-thinker', 'summers-free-thinker', 'typical-dead-boy-commando-durango', 'typical-cs-elite-rpa-pilot-durango', 'major-samuel-haim', 'orion-greenfeld', 'commander-jess-helgeland', 'sgt-samuel', 'corp-chase', 'corp-chesterfield', 'the-mighty-cassandra', 'hidechek-gezenske', 'manitoba-saskatchewan', 'dekker-tronsstedaal', 'serian-skeld', 'sir-jericho-camlann', 'omicron-lazlo-triad');

